"""Native fixed-context capsule; its table rel32 holes bind in the final BG pack."""
from pathlib import Path
from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_artifact_publication import document
from tools import generate_hia_background_optimizer_native_context_packers as original
ROOT=Path(__file__).resolve().parents[1]
CONFIG={'bridge': '', 'holes': {'policy': 232}, 'roles': ['policy'], 'export': 'hia_background_native_context', 'magic': 'HIABGCP3', 'relocations': [(1120, 'malloc'), (1134, 'free')]}
TABLE_HOLES={'queue': 360, 'ledger': 374, 'decimal': 388, 'jobs': 402, 'job_refs': 416, 'worker': 430, 'submission': 444, 'business': 458, 'execution': 472, 'account': 486, 'snapshot': 500, 'shutdown': 514, 'report': 528, 'structure_deferred': 542, 'transport_deferred': 556, 'freeze_deferred': 570, 'constructor': 584, 'options': 598, 'bridge_paths': 612, 'constructor_binding': 626, 'path_value': 640, 'path_resolve': 654, 'path_error': 668, 'path_string_codec': 682, 'posix_factory': 696, 'verifier': 710, 'json_capture': 724, 'sha256': 738, 'checked_freezer': 752, 'prepare_process': 766, 'verify_raw': 780, 'decision': 794, 'registry': 808, 'structure_compat': 833, 'transport_compat': 847, 'freeze_compat': 861, 'rank': 875, 'admission': 889, 'decision_policy': 903}
REAPER_HOLE=1234
def run(fn,*args):
    old=original.CONFIG['context']
    try:
        original.CONFIG['context']=CONFIG
        return fn('context',*args)
    finally:original.CONFIG['context']=old
def source_program():return run(original.source_program)
def reference_object(flats):return run(original.reference_object,flats)
def main():
    name='background_optimizer_native_reaper_context_packer'
    d=document(source_program(),name)
    p=ROOT/'examples/hia_bootstrap'/(name+'.hepta');p.write_text(render_assembly(d))
    print(p.name,p.stat().st_size,len(d['functions']),sum(len(f['blocks'])for f in d['functions']),
          sum(len(b['ops'])for f in d['functions']for b in f['blocks']),flush=True)
if __name__=='__main__':main()
